  var RIBO_ROUTE=['mrna-channel','trna-a','trna-p','peptide-center','trna-e'];
  var RIBO_CAPTIONS=['Messenger RNA places its message beside the small subunit. Each codon is a group of three RNA bases.','An incoming transfer RNA meets the message at the A site and presents its attached amino acid.','The P site holds a transfer RNA associated with the growing peptide during elongation.','The large subunit’s RNA forms the region where peptide bonds join amino acids.','The E site provides an exit position for a transfer RNA after it has given up its amino acid.'];
  function riboRouteNumber(value){return typeof value==='number'&&isFinite(value)?clamp(Math.round(value),1,5):1;}
  function riboRouteIndex(id){return typeof id==='string'?RIBO_ROUTE.indexOf(id)+1:0;}
  function riboPoint(id,separated){
    var p=typeof id==='string'&&RIBOSOME_STRUCTURE.landmarks.filter(function(v){return v.id===id;})[0];if(!p)return null;
    var at=p.at.slice(),view=p.view.slice(),length=Math.hypot.apply(Math,view);if(separated)at[1]+=p.part==='small'?-.16:p.part==='large'?.16:0;
    return {id:p.id,part:p.part,at:at,view:view.map(function(v){return v/length;}),zoom:p.zoom||3};
  }
  function riboRouteView(value){var n=riboRouteNumber(value),p=riboPoint(RIBO_ROUTE[n-1],false);p.n=n;return p;}
  function riboDetail(detail,separated){if(!detail||!detail.riboPart)return detail;var p=riboPoint(detail.id,separated);return p?Object.assign({},detail,{at:p.at,view:p.view}):detail;}
