      function fineTube(group,points,radius,mat,steps){var curve=new T.CatmullRomCurve3(points.map(function(p){return new T.Vector3(p[0],p[1],p[2]);}));return mesh(group,track(new T.TubeGeometry(curve,steps,radius,6,false)),mat);}
