      bead(respiratoryOut,[.0135,.048,-.038],[.014,.020,.018],respiratoryAnchor);
      link(respiratoryOut,[.017,.048,-.038],[.039,.048,-.038],.0075,respiratoryLink);
      bead(respiratoryOut,[.043,.052,-.045],[.012,.012,.013],respiratoryColor);
      bead(respiratoryOut,[.046,.044,-.031],[.012,.010,.012],respiratoryColor);
      bead(respiratoryOut,[.029,.055,-.034],[.009,.010,.011],respiratoryLink);
