        var arcGeo=track(new T.BufferGeometry());arcGeo.setAttribute('position',new T.Float32BufferAttribute(arcs,3));earthGroup.add(new T.LineSegments(arcGeo,track(new T.LineBasicMaterial({color:'#96c8db',transparent:true,opacity:.45,depthWrite:false}))));
